  "guide.apps.pleaseHelpMeConnect": "“Please help me connect to my Shopify store”",
  "apps.focusedSpacesSudoCan": "Apps that run fully on your Pi, nowhere else. Each one is yours to change: just ask your sudo what you would like to see. Reach them from anywhere by turning on Access from anywhere in Settings (an opt-in Cloudflare link), or make your own from scratch: tell your sudo your app idea.",
