  "key.removeConfirm": "Remove?",
  "key.which": "Which key should I get? ⓘ",
  "key.whichBody": "<strong>OpenRouter</strong> is the one to get if you get one: a single key for nearly every model, and it also powers reading images and searching your agent's memory.<br><br>A key straight from <strong>DeepSeek, OpenAI, Anthropic or Google</strong> runs your agent on that company's model, usually cheaper if you already pay them.<br><br>Keys stay on this device and only ever go to the company they belong to.",
