  "hub.faq.awayQ": "¿Puedo usarlo fuera de casa?",
  "hub.faq.awayA": "Sí. Activa Acceso desde cualquier lugar en Ajustes y sudo crea un enlace privado que funciona desde cualquier red. Trátalo como una contraseña y apágalo cuando no lo necesites.",
  "hub.faq.updatesQ": "¿Las actualizaciones borran mis cambios?",
  "hub.faq.updatesA": "No. Las actualizaciones cambian el código propio de sudo por la versión nueva. La memoria de tu asistente, tus ajustes, tus contactos y las apps que creaste se quedan.",
