  "hub.faq.costA": "El modelo de IA que conectas cobra por lo que usas. Pon un límite mensual en Ajustes, en Límite de gasto, y sudo se detiene antes de pasarse.",
  "hub.faq.safeQ": "¿Quién puede darle órdenes?",
