  "guide.cloud.whatSOnYour": "Lo que tiene tu Sudo hoy",
  "guide.cloud.yourSudoAlreadyHas": "Tu Sudo ya tiene un cerebro propio: <strong>Gemma 3 270M</strong>, un modelo pequeño que funciona por completo en el dispositivo. “270M” significa 270 millones de <em>parámetros</em>, los números con los que aprende un modelo. Más parámetros suele significar un modelo más capaz.",
  "guide.cloud.onYourSudoGemma": "En tu Sudo · Gemma 3 270M",
