  "guide.cloud.frontierCloudModelsChatgpt": "Modelos de punta en la nube (ChatGPT, Claude…)",
  "guide.cloud.notPublishedEstimatedHundreds": "No publicado · se calculan de cientos de miles de millones a billones",
  "guide.cloud.parametersOnALog": "Parámetros en escala logarítmica: cada línea es 10× la anterior. OpenAI no publica el tamaño de su modelo más avanzado de ChatGPT, así que esa barra es un cálculo externo y se muestra difuminada. *Una regla general, no un límite fijo.",
  "guide.cloud.whyAbout4Billion": "¿Por qué unos 4 mil millones en una Pi?",
  "guide.cloud.thePi5In": "La Pi 5 de tu Sudo tiene 4 GB de memoria, compartida con todo lo demás que ejecuta. Como regla general, ahí cabe un modelo de unos 4 mil millones de parámetros como máximo, y solo muy comprimido (“cuantizado”), para que cada parámetro ocupe medio byte en lugar de dos. Algo más grande simplemente no cabe, e incluso ese tamaño responde lento.",
  "guide.cloud.ourAdviceTheOn": "<strong>Nuestro consejo</strong> El modelo del dispositivo está bien para conversar. Para el trabajo diario, como correo, investigación y planificación, te recomendamos un modelo en la nube.",
  "guide.cloud.whatYourAgentIs": "De qué está hecho tu asistente",
  "guide.cloud.whatAnAgentIs": "De qué está hecho un asistente",
  "guide.cloud.memoryContextAndTools": "La memoria, el contexto y las herramientas se quedan contigo. El LLM se conecta debajo y se puede cambiar por ChatGPT, Claude, DeepSeek o cualquier otro modelo.",
  "guide.cloud.yoursToKeepGrows": "TUYO PARA SIEMPRE · CRECE CADA DÍA",
  "guide.cloud.memory": "Memoria",
  "guide.cloud.whatItKnows": "lo que sabe",
  "guide.cloud.context": "Contexto",
  "guide.cloud.yourLifeFiles": "tu vida, archivos",
