  "guide.cloud.appsTheWeb": "apps, la web",
  "guide.cloud.llmSwappable": "LLM · intercambiable",
  "guide.cloud.swapAnyTime": "cámbialo cuando quieras",
  "guide.cloud.orAlmostAnyOther": "…o casi cualquier otro modelo",
  "guide.cloud.memoryContextAndTools2": "<strong>La memoria, el contexto y las herramientas son tuyos.</strong> Son lo que tu asistente sabe de ti y lo que puede hacer por ti, y crecen cada día que lo usas.",
  "guide.cloud.theLlmIsThe": "<strong>El LLM es la parte que se cambia.</strong> Las empresas de IA se pasan unas a otras todo el tiempo: un mes lidera ChatGPT, al siguiente Claude o DeepSeek. Con Sudo no quedas atado. Cambia de modelo y conserva tu memoria y tu contexto. Sin empezar de cero.",
  "guide.cloud.openrouterOneKeyNearly": "OpenRouter: una clave, casi todos los modelos",
  "guide.cloud.youAddCreditTo": "Tú recargas saldo en OpenRouter; Sudo usa una sola clave de OpenRouter; OpenRouter llega a OpenAI, Anthropic, Google, DeepSeek y muchos más.",
  "guide.cloud.you": "Tú",
  "guide.cloud.credit": "saldo",
  "guide.cloud.oneKey": "una clave",
  "guide.cloud.manyMore": "+ muchos más",
  "guide.cloud.openrouterIsOneAccount": "OpenRouter es una sola cuenta con una clave API universal que llega a casi todos los modelos de IA. Recargas saldo ahí y OpenRouter les paga a las empresas de IA por ti.",
  "guide.cloud.createAnAccountAt": "Crea una cuenta en <a href=\"https://openrouter.ai\">openrouter.ai</a>.",
  "guide.cloud.addCreditYouChoose": "Recarga saldo. Tú eliges cuánto.",
  "guide.cloud.createAKeyUnder": "Crea una clave en <a href=\"https://openrouter.ai/settings/keys\">Keys</a> y pégala en Sudo: Ajustes → Claves API. Empieza con <code>sk-or-</code>.",
  "guide.cloud.sudoTakesNoCut": "Sudo no se queda con nada",
  "guide.cloud.youPayTheAi": "Les pagas a las empresas de IA a través de OpenRouter. Tu clave se queda en este dispositivo y nunca vemos tu factura.",
  "guide.cloud.openrouterSSmallFee": "La pequeña comisión de OpenRouter",
  "guide.cloud.openrouterAddsAFee": "OpenRouter cobra una comisión al comprar saldo: 5.5 % con tarjeta (5 % con cripto). Los precios de los modelos se cobran tal cual, sin recargo. Sudo no agrega nada. <a href=\"https://openrouter.ai/pricing\">Sus precios</a>",
  "guide.cloud.seeEveryCent": "Mira cada centavo",
  "guide.cloud.yourOpenrouterAccountShows": "Tu cuenta de OpenRouter muestra el saldo que te queda y un registro de cada solicitud: qué modelo, cuántos tokens y cuánto costó. <a href=\"https://openrouter.ai/settings/credits\">Saldo</a> · <a href=\"https://openrouter.ai/logs\">Registros</a>",
  "guide.cloud.aSpendingGuard": "Un límite de gasto",
  "guide.cloud.sudoSCircuitBreaker": "El freno de Sudo pausa a tu asistente cuando llega a un límite diario de mensajes. Tú eliges el límite.",
  "guide.cloud.openSpendingGuard": "Abrir Límite de gasto",
  "guide.cloud.whatItCosts": "Cuánto cuesta",
  "guide.cloud.modelsChargePerToken": "Los modelos cobran por token (más o menos ¾ de palabra) y los precios varían muchísimo:",
  "guide.cloud.model": "Modelo",
  "guide.cloud.in": "Entrada",
  "guide.cloud.out": "Salida",
  "guide.cloud.deepseekV4FlashRecommended": "DeepSeek V4 Flash <em>recomendado</em>",
  "guide.cloud.usDollarsPerMillion": "Dólares estadounidenses por millón de tokens en openrouter.ai, a octubre de 2026. Las barras muestran el precio de salida a escala. DeepSeek V4 Flash lo ofrecen varios proveedores a precios distintos; esta es la tarifa que cobran la mayoría. Los precios cambian, así que revisa la página del modelo para ver el de hoy.",
  "guide.cloud.aMonthIsWhat": "al mes es lo que la mayoría puede esperar con DeepSeek V4 Flash como modelo principal, nuestra opción recomendada. <small>Un cálculo típico, no una garantía: el uso intenso, los ayudantes y los modelos más caros cuestan más.</small>",
  "guide.cloud.preferFullyPrivate": "¿Prefieres total privacidad?",
  "guide.cloud.switchBackToThe": "Cambia al modelo del dispositivo cuando quieras en Inicio → Asistente y modelos → <em>Modelos en el dispositivo</em>. Es totalmente privado y gratis. También estamos preparando modelos locales comprimidos y ajustados para Sudo. Muy pronto.",
