  "set.channels.comingSoon": "Muy pronto",
  "set.channels.wantToGiveYour": "<strong>¿Quieres darle a tu asistente su propio número?</strong> Nosotros usamos Tello, una compañía telefónica externa: <a href=\"https://www.amazon.com/dp/B08H5SM9M9\">consigue una SIM de Tello</a>. Con un segundo número puedes crear una cuenta de WhatsApp aparte para tu asistente, y así te escribe desde su propio contacto en lugar de dentro de tu chat. <small>No es publicidad pagada; es simplemente lo que usamos. Cualquier compañía que te dé un número que pueda recibir SMS sirve, así que te animamos a buscar la que mejor te quede.</small>",
  "set.channels.close": "Cerrar",
