  "set.channels.offByDefaultRead": "Apagado de forma predeterminada. Solo lectura: puede ver tus chats con otras personas en tu propio WhatsApp vinculado, y nunca les responde.",
  "set.channels.whatItAllowsYour": "<strong>Qué permite.</strong> Tu asistente puede leer los chats de <em>tu propio</em> WhatsApp vinculado, es decir, tus conversaciones con otras personas, para recordarte cosas y notar quién está esperando tu respuesta.<br><br><strong>Qué nunca hace.</strong> Nunca responde a nadie en esos chats ni les escribe. Solo habla contigo.<br><br><strong>Solo tu propia cuenta.</strong> Esto aplica únicamente al WhatsApp vinculado como “Tu WhatsApp”. El número propio del asistente no tiene otros chats que leer.<br><br><strong>Apagado de forma predeterminada.</strong> No se lee nada hasta que lo actives. Al apagarlo, se detiene.",
