  "set.connectors.andMuchMoreTo": "…y muchas más. Para conectar una, solo pídeselo a tu asistente: te enviará un enlace para iniciar sesión. <a href=\"https://composio.dev/toolkits\">Ver todas las apps</a>",
  "set.connectors.whatIsComposioWhy": "¿Qué es Composio? Por qué lo usamos y tu privacidad ⓘ",
  "set.connectors.whyWeUseIt": "<strong>Por qué lo usamos.</strong> Conectar un asistente a tus apps una por una significa construir cada conexión tú mismo, y se rompen cada vez que una app cambia. Composio mantiene conexiones listas y actualizadas para más de 1,600 apps, así que inicias sesión en una app una vez y sudo puede usarla.<br><br><strong>Tus accesos.</strong> Inicias sesión en la página de cada app, así que sudo nunca ve tu contraseña. Composio guarda cifrado el acceso que le das, lo usa solo en el momento en que sudo pide hacer algo y nunca se lo pasa a sudo ni al modelo de IA. Puedes desconectar cualquier app cuando quieras desde tu panel de Composio.<br><br><strong>Privacidad.</strong> Composio dice que no vende ni comparte datos de tu cuenta de Google y que no usa tus datos para entrenar IA. Tiene auditorías independientes (SOC 2 Type II, ISO 27001). De forma predeterminada guarda un registro de lo que sudo hizo en cada app hasta por un año; hay una opción para evitarlo (Zero Data Retention), y puedes pedir a support@composio.dev que borre tus datos. <a href=\"https://composio.dev/privacy\">Política de privacidad</a> · <a href=\"https://trust.composio.dev\">Seguridad</a>",
  "set.connectors.otherWaysToExtend": "otras formas de ampliar sudo",
  "set.connectors.mcpServers": "Servidores MCP ⓘ",
  "set.connectors.mcpIsAnOpen": "<strong>MCP</strong> es un estándar abierto para darle nuevas habilidades a un asistente. Un servidor MCP es un pequeño programa que ofrece herramientas (leer esta base de datos, buscar en estos documentos, controlar esta app) y sudo puede usarlas.<br><br>Composio es la opción sin configuración; MCP es lo que usas cuando quieres algo específico o alojado por ti. Funciona en tu dispositivo, así que nada sale de tu red.<br><br><em>Todavía no está conectado</em>: necesita el mismo cuidado que ejecutar comandos, porque un servidor MCP es código en el que decidiste confiar.",
  "set.connectors.cliTools": "Herramientas de línea de comandos ⓘ",
  "set.connectors.commandLineProgramsAlready": "Programas de línea de comandos que ya están en el dispositivo: <code>git</code>, <code>curl</code>, <code>ffmpeg</code> y cualquier otro que instales. Es la opción más amplia y la que tiene menos protecciones.<br><br>Se activa en <strong>Lo que sudo puede hacer → Ejecutar comandos en este dispositivo</strong>. Lee primero la advertencia: una página web puede contener texto escrito para engañar a un asistente y hacer que ejecute algo dañino.",
  "settings.backToSettings": "Volver a Ajustes",
  "wifi.warn": "<strong>¿Vas a mover sudo a otro Wi‑Fi?</strong> El teléfono o la computadora que uses debe unirse a ese mismo Wi‑Fi para volver a abrir sudo, a menos que <strong>Acceso desde cualquier lugar</strong> esté activado.",
  "wifi.connectedTo": "Conectado a",
  "wifi.nearby": "Redes cercanas",
  "wifi.rescan": "Buscar de nuevo",
  "wifi.regionNote": "Se configuró desde tu teléfono al empezar. Decide qué canales Wi‑Fi puede usar sudo.",
  "dev.anywhere": "acceso desde cualquier lugar",
  "dev.terminal": "terminal y herramientas de programación",
  "settings.dashboard": "Panel de sudo",
  "settings.thisDevice": "Este dispositivo",
  "home.modelAsk": "¿Quieres otro modelo? Solo pídele a tu asistente que lo cambie. Cada modelo cuesta distinto por mensaje, así que te recomendamos dejar DeepSeek como el principal.",
  "home.mainTag": "Principal",
  "hub.furtherTitle": "Ir más allá",
  "hub.cc.title": "Trabaja en tu sudo con Claude Code",
  "hub.cc.sub": "Deja que Claude Code cambie cómo funciona tu sudo, y que tu asistente le pase trabajos de programación.",
  "hub.cc.intro": "Claude Code es el asistente de programación de Anthropic. Hay dos formas de usarlo con sudo.",
  "hub.cc.aTitle": "1. Claude Code en tu computadora",
  "hub.cc.a1": "En Claude Code en tu computadora, pide: <em>\"Hazme una clave SSH para mi sudo y muéstrame la clave pública.\"</em>",
  "hub.cc.a2": "Aquí, abre <strong>Ajustes → Acceso de desarrollador</strong>, activa el <strong>Acceso por terminal</strong>, pega la clave en <strong>¿Prefieres usar tu propia clave SSH?</strong> y toca <strong>Usar esta clave</strong>.",
  "hub.cc.a3": "De vuelta en Claude Code, pídele que se conecte con la dirección que aparece en Acceso de desarrollador (como <code>ssh tu@sudo.local</code>) y dile qué quieres cambiar. Tu computadora debe estar en el mismo Wi‑Fi.",
  "hub.cc.bTitle": "2. Tu asistente usa Claude Code",
  "hub.cc.b1": "En <strong>Ajustes → Acceso de desarrollador</strong>, toca <strong>Instalar Claude Code</strong>.",
  "hub.cc.b2": "Inicia sesión una vez con tu suscripción de Claude: desde tu computadora, conéctate por <code>ssh</code> como arriba, ejecuta <code>claude</code> y sigue los pasos.",
  "hub.cc.b3": "Luego solo pídeselo a tu asistente, por ejemplo <em>\"Usa Claude Code para hacerme una página de recetas.\"</em> Le pasa el trabajo y te avisa cuando termina.",
  "hub.cc.open": "Abrir Acceso de desarrollador",
