  "com.gateTitle": "Crea una cuenta para ver la comunidad",
  "com.gateBody": "Publicaciones de personas que crean con su sudo y un mapa de dónde viven los sudos. Tu sudo es tu inicio de sesión, así que no hay contraseña.",
