  "set.access.joinNetwork": "Conectarse a la red",
  "set.access.pickANetworkAbove": "Elige una red de arriba, escribe su contraseña y conéctate. Si abriste el panel desde la red de casa, la página se cortará unos segundos mientras sudo cambia de red; vuelve en la nueva dirección.",
  "set.access.aboutAccessFromAnywhere": "Sobre el acceso desde cualquier lugar",
  "set.access.normallyYourDashboardOnly": "Normalmente tu panel solo funciona en el Wi‑Fi de tu casa. Activa esto y sudo crea una dirección web pública que llega a tu dispositivo desde cualquier lugar; útil cuando sales.<br><br><strong>Trata ese enlace como una contraseña.</strong> No hay pantalla de inicio de sesión: cualquiera que lo tenga puede chatear con tu asistente y cambiar estos ajustes. No lo publiques ni se lo mandes a nadie a quien no le prestarías tu teléfono desbloqueado.<br><br>El enlace cambia cuando el dispositivo se reinicia. Apágalo cuando no lo necesites.",
  "set.access.copy": "Copiar",
  "set.access.passwordForThePublic": "contraseña del enlace público",
  "set.access.askForAPassword": "Pedir contraseña",
  "set.access.appliesToThePublic": "Solo para el enlace público. La red de casa nunca la pide.",
  "set.access.requireAPasswordOn": "Pedir contraseña en el enlace público",
  "set.access.changeIt": "Cambiarla",
  "set.access.atLeast10Characters": "al menos 10 caracteres",
  "set.access.savePassword": "Guardar contraseña",
  "set.access.stronglyRecommendedLeaveThis": "<strong>Muy recomendado: déjalo activado.</strong> Sin esto, el enlace público es una dirección web que abre tu panel a cualquiera que la tenga: sin inicio de sesión, sin límite de intentos, desde cualquier parte del mundo. Podrían leer tus chats, cambiar tus ajustes y usar tu saldo de API. Los enlaces se comparten, quedan registrados en los servicios donde los pegas y se reenvían por error.",
  "set.access.localDashboardHttpRaspberrypi": "Panel local: <strong>http://raspberrypi.local</strong>",
  "set.access.wiFiRegion": "Región del Wi‑Fi",
  "set.access.autoDetectedAtSetup": "Se detecta en la configuración. Controla qué canales de Wi‑Fi puede usar el dispositivo; cámbialo solo si lo llevaste a otro país.",
  "set.ssh.developerAccess": "Acceso para desarrollo",
  "set.ssh.terminalAccessSsh": "Acceso por terminal (SSH)",
  "set.ssh.logIntoThisDevice": "Entra a este dispositivo desde tu computadora y trabaja en él directamente.",
  "set.ssh.toggleTerminalAccess": "Activar o desactivar el acceso por terminal",
  "set.ssh.aboutTerminalAccess": "Sobre el acceso por terminal",
  "set.ssh.itSYourDevice": "Es tu dispositivo, así que puedes tener acceso total. Esto abre una forma de entrar desde una computadora en el Wi‑Fi de tu casa y usarlo como cualquier otra máquina: instalar cosas, leer archivos, cambiar cómo funciona sudo.<br><br><strong>No lo necesitas para el uso normal.</strong> Todo lo que el dispositivo debe hacer, lo hace desde este panel.<br><br><strong>Solo en el Wi‑Fi de casa.</strong> Nunca se puede llegar a esto desde internet, ni siquiera con <em>Acceso desde cualquier lugar</em> activado.<br><br>Los cambios que hagas a mano se pierden si alguna vez se vuelve a grabar el dispositivo.",
  "set.ssh.aboutThisPassword": "Sobre esta contraseña",
  "set.ssh.generatedJustNowFor": "Se acaba de generar para la cuenta de usuario de tu dispositivo. Guárdala en un lugar seguro; siempre puedes volver aquí para verla de nuevo mientras estés en el Wi‑Fi de tu casa.",
  "set.ssh.openThisPageOn": "Abre esta página en el Wi‑Fi de tu casa para ver la contraseña; no se muestra por el enlace público.",
  "set.ssh.preferToUseYour": "¿Prefieres usar tu propia clave SSH?",
  "set.ssh.aboutSshKeys": "Sobre las claves SSH",
  "set.ssh.anSshKeyIs": "Una clave SSH es un par de archivos en tu computadora: una mitad privada que nunca sale de ahí y una mitad pública que puedes compartir sin problema. Pones aquí la mitad pública, y tu computadora demuestra que tiene la privada al conectarse. Sin contraseña que escribir ni recordar.<br><br><strong>Si no tienes una</strong>, sáltate esto: la contraseña de arriba funciona bien. Para crear una, ejecuta <code>ssh-keygen -t ed25519</code> en tu computadora y luego pega el contenido de <code>~/.ssh/id_ed25519.pub</code>.",
  "set.ssh.useThisKeyInstead": "Usar esta clave",
  "set.ssh.aboutClaudeCode": "Sobre Claude Code",
  "set.ssh.claudeCodeIsAn": "Claude Code es un asistente de IA que funciona en una terminal y puede leer y cambiar los archivos de este dispositivo; útil si quieres personalizar cómo funciona sudo.<br><br>No viene preinstalado, para que el dispositivo ocupe poco y siempre tengas la versión actual. La instalación tarda unos minutos y necesita internet. Puedes ver el progreso aquí mismo.",
  "set.ssh.installClaudeCode": "Instalar Claude Code",
  "set.ssh.installedOpenATerminal": "Instalado. Abre una terminal en tu computadora y ejecuta esto:",
  "set.ssh.openaiSTerminalAssistant": "El asistente de terminal de OpenAI. La misma idea, otro proveedor; puedes tener los dos.",
  "set.ssh.installCodex": "Instalar Codex",
  "set.github.giveSudoAGithub": "Dale a sudo un token de GitHub y podrá trabajar con tus repositorios directamente (clonar uno, subir cambios, abrir un issue) en lugar de solo guiarte.",
  "set.github.githubUsername": "Usuario de GitHub",
  "set.github.optional": "opcional",
  "set.github.yourHandle": "tu-usuario",
  "set.github.personalAccessToken": "Token de acceso personal",
  "set.github.ghpOrGithubPat": "ghp_… o github_pat_…",
  "set.github.createOneAtGithub": "Créalo en <strong>github.com → Settings → Developer settings → Personal access tokens</strong>. Elige solo los permisos que sudo necesita; lo más seguro es un token detallado limitado a los repositorios que te importan. Se guarda solo en este dispositivo.",
  "set.github.saveToken": "Guardar token",
  "set.github.letSudoUseMy": "Dejar que sudo use mis repositorios",
  "set.github.whenOffTheToken": "Apagado, el token queda guardado pero sudo no puede entrar a GitHub.",
  "set.github.whatTheTokenCan": "Qué puede hacer el token ⓘ",
  "set.github.aTokenIsA": "Un token es una llave a tu cuenta de GitHub. Lo que puede alcanzar es exactamente lo que marcaste al crearlo: el acceso a repositorios deja que sudo clone, suba cambios y abra issues; nada más.<br><br><strong>Trátalo como una contraseña.</strong> Mantenlo apagado a menos que quieras a sudo trabajando en tus repositorios, y revócalo en GitHub en cuanto termines. Se guarda solo en este dispositivo y nunca sale de él, salvo para hablar con GitHub.",
  "settings.billingCredits": "Facturación y créditos",
  "set.billing.billingCredits": "Pagos y saldo",
  "set.billing.donTWantTo": "<strong>¿No quieres lidiar con claves API?</strong> Recarga aquí y nosotros nos encargamos del resto: sin cuentas que crear, sin claves que pegar, sin cobros de cada proveedor que vigilar.",
  "set.billing.usdCreditsAvailable": "saldo disponible en USD",
  "set.billing.startSudoPro10": "Empezar Sudo Pro · 10 USD al mes",
  "set.billing.includesA7Day": "Incluye 7 días de prueba. El pago se abre de forma segura en Stripe.",
  "settings.reset": "Restablecer",
