  "set.reset.putsThisDeviceBack": "Deja este dispositivo como salió de la caja: se olvida el Wi‑Fi de tu casa y vuelve la red <strong>RaspiSetup</strong>, así que el próximo arranque recorre toda la configuración desde el principio.",
  "set.reset.thisErasesYourSetup": "<strong>Esto borra tu configuración.</strong> Tu nombre, el nombre y la personalidad del asistente, su modelo, tus claves API guardadas y la memoria del asistente se van. El acceso por terminal y Claude Code se <em>conservan</em>, para que puedas volver a entrar a probar. Para volver a un dispositivo nuevo tendrás que configurarlo otra vez.",
