  "guide.cloud.yourSudoAlreadyHas": "你的 Sudo 已经自带一个大脑：<strong>Gemma 3 270M</strong>，一个完全在设备上运行的小模型。“270M”指 2.7 亿个<em>参数</em>，也就是模型用来学习的数字。参数越多，模型通常越强。",
