  "guide.cloud.notPublishedEstimatedHundreds": "未公开 · 估计在数千亿到数万亿之间",
  "guide.cloud.parametersOnALog": "参数数量，按对数刻度：每条网格线是前一条的 10 倍。OpenAI 没有公开 ChatGPT 最强模型的规模，所以那一条是外界估计，用渐隐表示。*只是经验值，不是硬性上限。",
  "guide.cloud.whyAbout4Billion": "为什么 Pi 大约只能跑 40 亿？",
  "guide.cloud.thePi5In": "你 Sudo 里的 Pi 5 有 4GB 内存，还要和它运行的其他程序共用。按经验，最多能装下约 40 亿参数的模型，而且必须大幅压缩（“量化”），让每个参数只占半个字节而不是两个。再大的模型根本装不下，就算这个大小，回答也很慢。",
  "guide.cloud.ourAdviceTheOn": "<strong>我们的建议</strong> 设备上的模型用来聊天没问题。处理邮件、查资料、做计划这类日常事务，我们建议用云端模型。",
