  "guide.cloud.memoryContextAndTools2": "<strong>记忆、上下文和工具是你的。</strong>它们是助手对你的了解和能为你做的事，用得越久，积累越多。",
  "guide.cloud.theLlmIsThe": "<strong>大模型是可以更换的部分。</strong>AI 公司你追我赶：这个月 ChatGPT 领先，下个月可能是 Claude 或 DeepSeek。用 Sudo 你不会被绑定。换模型时记忆和上下文都还在，不用从头再来。",
  "guide.cloud.openrouterOneKeyNearly": "OpenRouter：一个密钥，几乎所有模型",
