  "guide.cloud.openrouterSSmallFee": "OpenRouter 的少量手续费",
  "guide.cloud.openrouterAddsAFee": "OpenRouter 在你充值时收取手续费：刷卡 5.5%（加密货币 5%）。模型价格原价转给你，不加价。Sudo 不额外收费。<a href=\"https://openrouter.ai/pricing\">查看价格</a>",
  "guide.cloud.seeEveryCent": "每一分钱都看得到",
  "guide.cloud.yourOpenrouterAccountShows": "你的 OpenRouter 账户会显示剩余额度和每次请求的记录：用了哪个模型、多少 token、花了多少钱。<a href=\"https://openrouter.ai/settings/credits\">额度</a> · <a href=\"https://openrouter.ai/logs\">记录</a>",
  "guide.cloud.aSpendingGuard": "花费保护",
