  "guide.cloud.aMonthIsWhat": "每月，这是大多数人以 DeepSeek V4 Flash（我们推荐的默认模型）为主时的花费。<small>只是常见估算，不是保证：用得多、开启帮手或用更贵的模型都会更贵。</small>",
