  "key.whichBody": "如果只要一个，选 <strong>OpenRouter</strong>：一个密钥几乎能用所有模型，还支持读图和搜索助手的记忆。<br><br>直接来自 <strong>DeepSeek、OpenAI、Anthropic 或 Google</strong> 的密钥会让助手使用该公司的模型；如果你已经在付费，通常更便宜。<br><br>密钥保存在这台设备上，只会发给它所属的公司。",
