  "set.routing.modelRouting": "模型与路由",
  "set.routing.whichModelAnswersYou": "由哪个模型来回答你。“自动”会为每条消息选最划算又靠谱的模型；“固定”则一直用你选的那个。",
  "set.routing.answeringRightNow": "当前回答的模型",
  "set.routing.keepItOnThis": "只在这台设备上运行",
  "set.routing.answerWithTheOn": "即使保存了密钥，也用设备上的模型回答。你输入的内容不会离开家。",
  "set.routing.preferTheOnDevice": "优先使用设备上的模型",
  "set.routing.whatYouGiveUp": "你会失去什么 ⓘ",
  "set.routing.theOnDeviceModel": "设备上的模型很小，大约只有云端模型的千分之一。它能跟你打招呼、聊天、处理简单的事，但不能上网搜索、不能推理复杂的问题，也看不了图片。<br><br>它完全免费，断网也能用。<br><br>如果还没装好，消息会照常发到云端，不会失败。",
  "set.routing.automatic": "自动",
  "set.routing.picksPerMessageCheapest": "每条消息单独挑选，选能胜任的最便宜的。",
  "set.routing.alwaysThisOne": "固定用这个",
  "set.routing.sameModelEveryTime": "每次都用同一个模型。",
  "set.routing.howAutomaticRoutingPicks": "自动路由怎么选 ⓘ",
  "set.routing.shortAndSimpleAsks": "<strong>简短简单的问题</strong>交给最便宜的文字模型，大多数消息都属于这一类。<br><br><strong>带图片的内容</strong>交给真正看得见的模型；默认模型只认文字，没有这一步它只能瞎猜。<br><br><strong>又长又多步骤的任务</strong>会升级到更强的模型，因为便宜模型在难题上反复打转，比好模型一次做完更花钱。<br><br>按消息计费，所以“自动”通常比所有消息都用强模型更省钱。",
  "set.routing.aboutModels": "关于模型",
  "set.routing.theBrainYourAgent": "助手用来思考的大脑。四个模型每条消息的价格不同：便宜的更快，日常聊天足够；贵的在难题上推理更好。<br><br><strong>DeepSeek V4 Flash</strong>：默认模型，也是目前最便宜的。只认文字，看不了你发的照片。<br><strong>GPT-4o mini</strong>：便宜又快，能看图片。<br><strong>Claude Haiku 4.5</strong>：质量更上一层，能看图片。<br><strong>Claude Sonnet 4.5</strong>：这里最强也最贵，适合复杂的多步骤任务。<br><br>想换随时换。如果你把照片发给看不见图的模型，sudo 会转交给看得见的模型。",
  "set.routing.optDefault": "DeepSeek V4 Flash · 默认",
