  "set.github.personalAccessToken": "个人访问令牌",
  "set.github.ghpOrGithubPat": "ghp_… 或 github_pat_…",
  "set.github.createOneAtGithub": "在 <strong>github.com → Settings → Developer settings → Personal access tokens</strong> 创建。只勾选 sudo 需要的权限；最安全的是只限于你关心的仓库的细粒度令牌。只保存在这台设备上。",
  "set.github.saveToken": "保存令牌",
  "set.github.letSudoUseMy": "允许 sudo 使用我的仓库",
  "set.github.whenOffTheToken": "关闭时，令牌仍然保存着，但 sudo 无法访问 GitHub。",
  "set.github.whatTheTokenCan": "令牌能做什么 ⓘ",
  "set.github.aTokenIsA": "令牌是打开你 GitHub 账户的一把钥匙。它能访问的范围，正是你创建时勾选的权限：仓库权限让 sudo 能克隆、推送和提交 issue，别的都不行。<br><br><strong>请像对待密码一样对待它。</strong>除非你想让 sudo 在你的仓库里工作，否则保持关闭；用完立刻在 GitHub 上撤销。它只保存在这台设备上，除了和 GitHub 通信，从不离开设备。",
  "settings.billingCredits": "计费与额度",
