  "set.reset.thisErasesYourSetup": "<strong>这会清除你的设置。</strong>你的名字、助手的名字和性格、它的模型、你保存的 API 密钥，以及助手的记忆都会被删除。终端访问和 Claude Code 会<em>保留</em>，方便你重新登录测试。要恢复成全新设备，必须重新设置一遍。",
