  "crm.build.title": "建立你的联系人 — 从 LinkedIn 和 Instagram 导入",
  "crm.build.intro": "把已经认识的人加进来。这样你的助手就能给允许的人发消息、提醒你该跟谁联系，也不会漏掉任何一条线索。导入名单有两种方式，任选其一或都用。",
  "crm.build.linkedinTitle": "从 LinkedIn",
