  "crm.build.li3": "LinkedIn 会给你发一封带 CSV 文件的邮件。下载它。",
  "crm.build.li4": "在这里对你的助手说：<em>“把这些人都加到我的联系人里”</em> 并附上 CSV，或者说 <em>“我导出了 LinkedIn 的联系人”</em>，它会一步步带你完成。",
  "crm.build.liPrompt": "我想添加我的 LinkedIn 联系人。我已经从 LinkedIn 导出了，帮我导入。",
  "crm.build.instagramTitle": "从 Instagram",
  "crm.build.igIntro": "Instagram 不能一键导出你的关注者，但你可以<strong>下载你的信息</strong>，名单就在里面。",
  "crm.build.ig1": "在 Instagram 应用里：<strong>个人主页 → 菜单（☰）→ 你的动态 → 下载你的信息</strong>。",
  "crm.build.ig2": "选择 <strong>关注者和正在关注</strong>（取消勾选其余项以加快速度），格式选 <strong>JSON</strong>，然后点 <strong>请求下载</strong>。",
  "crm.build.ig3": "准备好后 Instagram 会给你发一封带链接的邮件——通常几分钟，有时要几个小时。下载并解压。",
  "crm.build.ig4": "对你的助手说：<em>“把我在 Instagram 上关注的人加到我的联系人里”</em> 并附上文件。注意 Instagram 给的是用户名而不是电话号码——助手可以先把他们存为联系人，号码可以之后聊天时再补。",
  "crm.build.igPrompt": "我下载了 Instagram 的信息，想把我在上面关注的人加到联系人里。",
  "crm.build.linkTitle": "把每个人对应到正确的号码",
  "crm.build.linkIntro": "只有名字还不够——要在 WhatsApp 上给别人发消息，助手需要他们的号码。三种补齐的方法：",
  "crm.build.link1": "在上面的列表里手动填号码（<strong>添加</strong>框）。对最重要的少数几个人来说最快。",
  "crm.build.link2": "聊过之后问你的助手：<em>“Rosa 的号码是多少？”</em>，它会把名字和它看到的号码对应起来。",
  "crm.build.link3": "在 渠道 → WhatsApp 中打开 <strong>让我的助手读取我的其他 WhatsApp 聊天</strong>。当有新人给你发消息时，助手可以问你要不要加他——完全不用输入号码。",
