  "guide.cloud.parametersOnALog": "عدد المعاملات على مقياس لوغاريتمي: كل خط يساوي 10 أضعاف الذي قبله. لا تنشر OpenAI حجم أقوى نماذج ChatGPT، لذا فهذا الشريط تقدير خارجي ويظهر باهتًا. *قاعدة تقريبية لا حدّ صارم.",
