  "guide.cloud.thePi5In": "يحتوي Pi 5 داخل جهاز Sudo على ذاكرة بسعة 4 غيغابايت، يتقاسمها مع كل ما يشغّله. وكقاعدة تقريبية يتّسع ذلك لنموذج من نحو 4 مليارات معامل على الأكثر، وبعد ضغطه بشدة («التكميم») ليشغل كل معامل نصف بايت بدلًا من بايتين. أي نموذج أكبر لن يتّسع ببساطة، وحتى بهذا الحجم تكون الإجابات بطيئة.",
