  "set.channels.comingSoon": "قريبًا",
  "set.channels.wantToGiveYour": "<strong>تريد أن تمنح مساعدك رقم هاتف خاصًا به؟</strong> نحن نستخدم Tello، وهي شركة اتصالات خارجية: <a href=\"https://www.amazon.com/dp/B08H5SM9M9\">احصل على شريحة Tello</a>. برقم ثانٍ يمكنك إنشاء حساب WhatsApp منفصل لمساعدك، فيراسلك من جهة اتصاله الخاصة بدلًا من داخل محادثتك. <small>ليس إعلانًا مدفوعًا، إنها فقط ما نستخدمه. أي شركة تمنحك رقمًا يستقبل الرسائل النصية ستفي بالغرض، فننصحك بالبحث عمّا يناسبك.</small>",
  "set.channels.close": "إغلاق",
  "set.channels.settingsTitle": "إعدادات WhatsApp",
  "set.channels.whatsappOptions": "خيارات WhatsApp",
  "set.channels.offByDefaultRead": "متوقف افتراضيًا. للقراءة فقط: يرى محادثاتك مع الآخرين على WhatsApp المرتبط بك، ولا يردّ عليهم أبدًا.",
  "set.channels.whatItAllowsYour": "<strong>ما الذي يتيحه.</strong> يستطيع مساعدك قراءة المحادثات على WhatsApp <em>الخاص بك</em> المرتبط، أي محادثاتك مع الآخرين، ليذكّرك بالأمور ويلاحظ من ينتظر ردّك.<br><br><strong>ما لا يفعله أبدًا.</strong> لا يردّ على أحد في تلك المحادثات ولا يراسلهم. يتحدث معك أنت فقط.<br><br><strong>حسابك أنت فقط.</strong> ينطبق هذا على WhatsApp المرتبط باسم «WhatsApp الخاص بك» فقط. أما رقم المساعد الخاص فليس فيه محادثات أخرى ليقرأها.<br><br><strong>متوقف افتراضيًا.</strong> لا يُقرأ شيء حتى تشغّله. وإيقافه يوقف القراءة.",
  "set.channels.offByDefaultYour": "متوقف افتراضيًا. سيذكر ملخصك اليومي وتذكيراتك أيضًا من قد ينتظر ردًّا منك. يتطلب تشغيل الخيار أعلاه.",
  "conn.letSudoUseYour": "دع sudo يستخدم تطبيقاتك الأخرى (يرسل البريد، ويضيف المواعيد إلى التقويم، ويسجّل المشكلات) بدلًا من الحديث عنها فقط.",
  "set.connectors.connectorsLetSudoUse": "تتيح الموصّلات لـ sudo استخدام تطبيقاتك الأخرى (إرسال البريد، وإضافة المواعيد إلى التقويم، وتسجيل المشكلات) بدلًا من الحديث عنها فقط.",
  "set.connectors.composioApiKey": "مفتاح API لـ Composio",
  "set.connectors.pasteYourKey": "الصق مفتاحك",
  "set.connectors.fromDashboardComposioDev": "من <strong>dashboard.composio.dev</strong> ← Connect ← Settings ← Sessions &amp; API Key. يبدأ بـ <code>ck_</code>. يُحفظ على هذا الجهاز فقط، وحفظه يشغّل الموصّلات.",
  "set.connectors.saveKey": "حفظ المفتاح",
  "set.connectors.removeKey": "إزالة المفتاح",
  "set.connectors.whatYouCanConnect": "ما يمكنك ربطه",
  "set.connectors.1600AppsYour": "أكثر من 1600 تطبيق يستطيع مساعدك استخدامها",
  "set.connectors.andMuchMoreTo": "…وغيرها الكثير. لربط أيٍّ منها اطلب ذلك من مساعدك فقط، وسيرسل لك رابط تسجيل الدخول. <a href=\"https://composio.dev/toolkits\">شاهد كل التطبيقات</a>",
  "set.connectors.whatIsComposioWhy": "ما هو Composio؟ لماذا نستخدمه، وخصوصيتك ⓘ",
  "set.connectors.whyWeUseIt": "<strong>لماذا نستخدمه.</strong> ربط المساعد بتطبيقاتك واحدًا تلو الآخر يعني أن تبني كل اتصال بنفسك، وهي تتعطل كلما تغيّر التطبيق. يحتفظ Composio باتصالات جاهزة ومُحدَّثة بأكثر من 1600 تطبيق، فتسجّل الدخول إلى التطبيق مرة ويستطيع sudo استخدامه.<br><br><strong>بيانات دخولك.</strong> تسجّل الدخول في صفحة كل تطبيق نفسه، فلا يرى sudo كلمة مرورك أبدًا. يخزّن Composio صلاحية الوصول الممنوحة له مشفّرة، ولا يستخدمها إلا لحظة يطلب sudo تنفيذ شيء، ولا يمرّرها أبدًا إلى sudo أو إلى نموذج الذكاء الاصطناعي. ويمكنك فصل أي تطبيق في أي وقت من لوحة Composio.<br><br><strong>الخصوصية.</strong> يقول Composio إنه لا يبيع بيانات حساب Google الخاص بك ولا يشاركها، ولا يستخدم بياناتك لتدريب الذكاء الاصطناعي. وهو خاضع لتدقيق مستقل (SOC 2 Type II وISO 27001). افتراضيًا يحتفظ بسجل لما فعله sudo في كل تطبيق لمدة تصل إلى سنة؛ وهناك إعداد لإيقاف ذلك (Zero Data Retention)، ويمكنك أن تطلب من support@composio.dev حذف بياناتك. <a href=\"https://composio.dev/privacy\">سياسة الخصوصية</a> · <a href=\"https://trust.composio.dev\">الأمان</a>",
  "set.connectors.otherWaysToExtend": "طرق أخرى لتوسيع sudo",
  "set.connectors.mcpServers": "خوادم MCP ⓘ",
  "set.connectors.mcpIsAnOpen": "<strong>MCP</strong> معيار مفتوح لمنح المساعد قدرات جديدة. خادم MCP برنامج صغير يقدّم أدوات (قراءة قاعدة البيانات هذه، والبحث في هذه المستندات، والتحكم في هذا التطبيق)، ويستطيع sudo استدعاءها.<br><br>Composio هو الخيار الذي لا يحتاج إلى إعداد؛ أما MCP فتلجأ إليه حين تريد شيئًا محددًا أو مستضافًا لديك. يعمل على جهازك، فلا يخرج شيء من شبكتك.<br><br><em>لم يُفعَّل بعد</em>: يحتاج إلى الحذر نفسه الذي يتطلبه تشغيل الأوامر، لأن خادم MCP شيفرة اخترت أن تثق بها.",
  "set.connectors.cliTools": "أدوات سطر الأوامر ⓘ",
  "set.connectors.commandLineProgramsAlready": "برامج سطر الأوامر الموجودة على الجهاز: <code>git</code> و<code>curl</code> و<code>ffmpeg</code> وأي شيء آخر تثبّته. إنها الخيار الأوسع والأقل حماية.<br><br>تُشغَّل من <strong>ما يستطيع sudo فعله ← تشغيل الأوامر على هذا الجهاز</strong>. اقرأ التحذير هناك أولًا: قد تحتوي صفحة ويب على نص مكتوب لخداع المساعد ودفعه إلى تشغيل شيء ضار.",
  "settings.backToSettings": "العودة إلى الإعدادات",
  "wifi.warn": "<strong>ستنقل sudo إلى شبكة Wi‑Fi أخرى؟</strong> يجب أن ينضم الهاتف أو الحاسوب الذي تستخدمه إلى الشبكة نفسها لتفتح sudo مجددًا، ما لم يكن <strong>الوصول من أي مكان</strong> مفعّلًا.",
  "wifi.connectedTo": "متصل بـ",
