  "home.modelAsk": "تريد نموذجًا آخر؟ اطلب من مساعدك أن يبدّله. تختلف تكلفة النماذج لكل رسالة، لذا ننصح بإبقاء DeepSeek نموذجك الرئيسي.",
  "home.mainTag": "الرئيسي",
  "hub.furtherTitle": "للمزيد",
  "hub.cc.title": "اعمل على sudo باستخدام Claude Code",
  "hub.cc.sub": "دع Claude Code يغيّر طريقة عمل sudo، ودع مساعدك يسلّمه مهام البرمجة.",
  "hub.cc.intro": "Claude Code هو مساعد البرمجة من Anthropic. هناك طريقتان لاستخدامه مع sudo.",
  "hub.cc.aTitle": "1. Claude Code على حاسوبك",
  "hub.cc.a1": "في Claude Code على حاسوبك، اطلب: <em>«أنشئ لي مفتاح SSH لجهاز sudo وأرني المفتاح العام.»</em>",
  "hub.cc.a2": "هنا، افتح <strong>الإعدادات ← وصول المطوّر</strong>، وشغّل <strong>الوصول عبر الطرفية</strong>، والصق المفتاح تحت <strong>تفضّل استخدام مفتاح SSH الخاص بك؟</strong> ثم اضغط <strong>استخدم هذا المفتاح</strong>.",
  "hub.cc.a3": "عد إلى Claude Code واطلب منه الاتصال بالعنوان الظاهر في وصول المطوّر (مثل <code>ssh you@sudo.local</code>) وأخبره بما تريد تغييره. يجب أن يكون حاسوبك على شبكة Wi‑Fi نفسها.",
  "hub.cc.bTitle": "2. مساعدك يستخدم Claude Code",
  "hub.cc.b1": "في <strong>الإعدادات ← وصول المطوّر</strong>، اضغط <strong>ثبّت Claude Code</strong>.",
  "hub.cc.b2": "سجّل الدخول مرة واحدة باشتراكك في Claude: من حاسوبك، اتصل عبر <code>ssh</code> كما في الأعلى، وشغّل <code>claude</code>، واتبع خطوات الدخول.",
  "hub.cc.b3": "ثم اطلب من مساعدك، مثل <em>«استخدم Claude Code لتصنع لي صفحة لوصفاتي.»</em> سيسلّمه المهمة ويخبرك عند الانتهاء.",
  "hub.cc.open": "افتح وصول المطوّر",
