  "set.routing.whichModelAnswersYou": "أيّ نموذج يجيبك. التلقائي يختار أرخص خيار مناسب لكل رسالة؛ والثابت يستخدم دائمًا النموذج الذي تختاره.",
  "set.routing.answeringRightNow": "يجيب الآن",
  "set.routing.keepItOnThis": "إبقاؤه على هذا الجهاز",
  "set.routing.answerWithTheOn": "أجب بالنموذج المحلي حتى لو كان هناك مفتاح محفوظ. لا يخرج شيء مما تكتبه من المنزل.",
  "set.routing.preferTheOnDevice": "تفضيل النموذج المحلي",
  "set.routing.whatYouGiveUp": "ما الذي تتخلى عنه ⓘ",
  "set.routing.theOnDeviceModel": "النموذج المحلي صغير، يقارب جزءًا من ألف من حجم النماذج السحابية. يستطيع أن يحيّيك ويدردش ويتعامل مع الأمور البسيطة، لكنه لا يستطيع البحث في الويب أو التفكير في أمر طويل أو رؤية الصور.<br><br>تشغيله مجاني ويعمل حتى عند انقطاع الإنترنت.<br><br>إن لم يكن مثبّتًا بعد، فستذهب الرسائل إلى السحابة بدلًا من أن تفشل.",
  "set.routing.automatic": "تلقائي",
  "set.routing.picksPerMessageCheapest": "يختار لكل رسالة الأرخص القادر على المهمة.",
  "set.routing.alwaysThisOne": "هذا دائمًا",
  "set.routing.sameModelEveryTime": "النموذج نفسه في كل مرة.",
  "set.routing.howAutomaticRoutingPicks": "كيف يختار التوجيه التلقائي ⓘ",
  "set.routing.shortAndSimpleAsks": "<strong>الطلبات القصيرة والبسيطة</strong> تذهب إلى أرخص نموذج نصي، وهنا تقع معظم الرسائل.<br><br><strong>أي شيء فيه صورة</strong> يذهب إلى نموذج يرى فعلًا؛ فالافتراضي نصي فقط، وبدون هذا سيخمّن.<br><br><strong>العمل الطويل أو متعدد الخطوات</strong> يُرفَع إلى نموذج أقوى، لأن نموذجًا رخيصًا يدور في حلقة على مهمة صعبة يكلّف أكثر من نموذج جيد ينجزها مرة واحدة.<br><br>المحاسبة لكل رسالة، لذا فالتلقائي يكلّف عادةً أقل من تثبيت كل شيء على نموذج قوي واحد.",
  "set.routing.aboutModels": "عن النماذج",
  "set.routing.theBrainYourAgent": "العقل الذي يفكّر به مساعدك. تختلف تكلفة الرسالة بين النماذج الأربعة: الأرخص أسرع ومناسب للدردشة اليومية، والأغلى يفكّر أفضل في المسائل الصعبة.<br><br><strong>DeepSeek V4 Flash</strong>: الافتراضي والأرخص بفارق كبير. نصي فقط، فلا يرى الصور التي ترسلها.<br><strong>GPT-4o mini</strong>: رخيص وسريع، ويقرأ الصور.<br><strong>Claude Haiku 4.5</strong>: جودة أعلى بدرجة، ويقرأ الصور.<br><strong>Claude Sonnet 4.5</strong>: الأقوى هنا والأغلى. الأفضل للأعمال المعقدة متعددة الخطوات.<br><br>بدّل متى شئت. وإن أرسلت صورة إلى نموذج لا يرى، يحوّلها sudo إلى نموذج يرى.",
  "set.routing.optDefault": "DeepSeek V4 Flash · الافتراضي",
  "set.routing.optFast": "GPT-4o mini · سريع",
  "set.routing.optBudget": "Claude Haiku 4.5 · متوازن",
  "set.routing.optSmart": "Claude Sonnet 4.5 · ذكي",
  "set.routing.onDeviceGreeter": "النموذج المحلي",
  "set.routing.whatThisIs": "ما هذا ⓘ",
  "set.routing.gemma3270mAbout": "<strong>Gemma 3 270M</strong>، بحجم 200 ميغابايت تقريبًا، يعمل على Pi لا في السحابة. يحيّيك ويُبقي sudo قادرًا على الحديث حين لا يوجد مفتاح API أو إنترنت.<br><br>صغير عن قصد: سريع الرد، لكنه لا يتصفح الويب ولا يتذكر المحادثات السابقة ولا يجيب عن الأسئلة المعرفية. هذه مهمة النموذج السحابي.<br><br>يُنزَّل تلقائيًا بعد دقائق من اتصال الجهاز بشبكة Wi-Fi لأول مرة. إن ظل يقول <em>غير مثبّت</em> بعد ذلك بوقت طويل، فالجهاز لم يتمكن من الوصول إلى التنزيل.",
  "set.files.whatSudoKnows": "ما يعرفه sudo",
  "set.files.thesePlainTextFiles": "هذه الملفات النصية هي شخصية مساعدك وكل ما تذكّره عنك. لا شيء مخفي، اقرأ منها ما شئت.",
  "set.files.storedOnThisDevice": "محفوظة على هذا الجهاز في <code>/opt/sudo/agent-workspace</code>. لتعديلها، شغّل الوصول عبر الطرفية أدناه.",
  "set.theme.look": "المظهر",
  "set.theme.coloursOnlyNothingChanges": "الألوان فقط، ولا يتغير شيء في سلوك sudo. يُطبَّق فور اختيارك.",
  "settings.apiManagement": "إدارة مفاتيح API",
  "set.providers.apiKeysBillingSource": "مفاتيح API وطريقة الدفع",
  "set.providers.whereYourAiUsage": "أين تُحتسب تكلفة استخدامك للذكاء الاصطناعي",
  "set.providers.aboutApiKeys": "عن مفاتيح API",
  "set.providers.yourAgentThinksBy": "يفكّر مساعدك عبر استدعاء نماذج الذكاء الاصطناعي، ولا بد أن يدفع أحدٌ ثمن كل استدعاء.<br><br><strong>مفتاحك الخاص</strong>: تسجّل في <code>openrouter.ai</code>، وتلصق مفتاحك هنا، وتدفع لهم مباشرة. يبقى المفتاح على هذا الجهاز ولا يصل إلينا أبدًا. لا حسابات تنشئها لدينا ولا اشتراك.",
  "set.providers.sudoCredits": "رصيد Sudo",
