  "set.ssh.aboutSshKeys": "عن مفاتيح SSH",
  "set.ssh.anSshKeyIs": "مفتاح SSH زوج من الملفات على حاسوبك: نصف خاص لا يغادره أبدًا، ونصف عام يمكن مشاركته بأمان. تضع النصف العام هنا، فيُثبت حاسوبك عند الاتصال أنه يملك النصف الخاص. لا كلمة مرور تكتبها أو تتذكرها.<br><br><strong>إن لم يكن لديك مفتاح</strong>، تخطَّ هذا، فكلمة المرور أعلاه تكفي. لإنشاء مفتاح، شغّل <code>ssh-keygen -t ed25519</code> على حاسوبك، ثم الصق محتوى <code>~/.ssh/id_ed25519.pub</code>.",
